import { Struct, PublicKey, UInt64, Bytes, UInt32, Checksum512, PrivateKey } from '@wharfkit/antelope';

declare class SealedMessage extends Struct {
    from: PublicKey;
    nonce: UInt64;
    ciphertext: Bytes;
    checksum: UInt32;
}
declare function createSymmetricKey(secret: Checksum512, nonce: UInt64): Uint8Array;
declare function createIV(nonce: UInt64, secret: Checksum512): Checksum512;
declare function encryptMessage(iv: Checksum512, symmetricKey: Uint8Array, message: string): Bytes;
declare function decryptMessage(iv: Checksum512, symmetricKey: Uint8Array, message: Bytes): Uint8Array;
/**
 * Seals a message using AES encryption and a shared secret derived from given keys.
 * @param message - The message to seal
 * @param privateKey - The private key to use for encryption
 * @param publicKey - The public key to use for encryption
 * @param nonce - A nonce to use for encryption
 * @returns The sealed message as Bytes
 */
declare function sealMessage(message: string, privateKey: PrivateKey, publicKey: PublicKey, nonce: UInt64): Bytes;
declare function sealedMessagePayload(message: string, privateKey: PrivateKey, publicKey: PublicKey, nonce?: UInt64): SealedMessage;
/**
 * Decrypt a message using AES and shared secret derived from given keys.
 * @param message - The encrypted message bytes to decrypt
 * @param privateKey - The private key to use for deriving the shared secret
 * @param publicKey - The public key to use for deriving the shared secret
 * @param nonce - The nonce used in the encryption process
 * @returns The decrypted message as a UTF-8 string
 * @internal
 */
declare function unsealMessage(message: Bytes, privateKey: PrivateKey, publicKey: PublicKey, nonce: UInt64): string;

export { SealedMessage, createIV, createSymmetricKey, decryptMessage, encryptMessage, sealMessage, sealedMessagePayload, unsealMessage };
